  rarity = excluded.rarity,
  type = excluded.type,
  year = excluded.year,
  era = excluded.era,
  power = excluded.power,
  views = excluded.views,
  languages = excluded.languages,
  description = excluded.description,
  short = excluded.short,
  summary = excluded.summary,
  image = excluded.image,
  wiki_title = excluded.wiki_title,
  url = excluded.url,
  fr = excluded.fr,
  source = excluded.source,
  revision = excluded.revision,
  story_text = excluded.story_text,
  updated_at = now();

insert into public.catalog_info (id, generated_at, popularity, license)
select true, generated_at, popularity, license
from jsonb_populate_record(null::public.catalog_info, $info${"generated_at":"2026-09-30T19:21:02.000Z","popularity":{"metric":"English Wikipedia page views and number of Wikipedia languages","days":60,"until":"2026-09-29"},"license":"Card texts come from Wikipedia (CC BY-SA 4.0, https://creativecommons.org/licenses/by-sa/4.0/). Pictures belong to their respective owners, see each picture's file page on Wikipedia."}$info$::jsonb)
on conflict (id) do update set
  generated_at = excluded.generated_at,
  popularity = excluded.popularity,
  license = excluded.license;
